import {validateReport,metrics,insights,filterSystems,inventoryCsv,categories} from './model.js';
const $=id=>document.getElementById(id);
const escape=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const categoryKey=c=>c.toLowerCase();
const colors={ERP:'#a9f5ce',Email:'#8fb7ff',Finance:'#f0cf87',CRM:'#d0a1ff',People:'#f1a8b9',Collaboration:'#85dcd5',Data:'#89c7ed',Infrastructure:'#a5afbd',Unclassified:'#e3b88c'};
const initials=name=>name.replace(/Microsoft |Oracle /g,'').split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const badge=(state,label)=>`<span class="badge ${escape(state)}">${escape(label||({observed:'Observed',reported:'Owner reported',inferred:'Needs verification',complete:'Complete',error:'Needs attention',not_configured:'Not configured'}[state]||state))}</span>`;
const sourceNames={endpoint:'Endpoint inventory',dns:'Mail DNS',m365:'Microsoft 365',endpoints:'HTTPS fingerprint',inventory:'Owner inventory'};
let report, sample, view='map', query='', category='all', state='all', timer=null, replayIndex=null, toastTimer;
let replayBase=null;
const viewInfo={map:['Company map','Company connectome','Your operating systems, with the evidence that connects them.'],inventory:['System inventory','System inventory','Inspect each application, its owner, and how it was discovered.'],sources:['Discovery sources','Know what you can see.','Every discovery source has a scope, an outcome, and a boundary.'],insights:['Evidence & gaps','The next questions to ask.','Review findings grounded in this inventory. Confirm them with your team.']};

function notify(message,error=false){$('toast').textContent=message;$('toast').className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').className='',6000);}
function saveFile(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function stopReplay(){clearInterval(timer);timer=null;replayIndex=null;replayBase=null;}
function activeReport(){
  if(replayIndex===null)return report;
  const base=replayBase||sample;
  const visibleSources=new Set(base.collectors.slice(0,replayIndex).filter(c=>c.status==='complete').map(c=>c.id));
  const systems=base.systems.filter(s=>s.evidence.some(e=>visibleSources.has(e.source))).map(s=>({...s,evidence:s.evidence.filter(e=>visibleSources.has(e.source))}));
  const ids=new Set(systems.map(s=>s.id));
  return {...base,systems,relationships:base.relationships.filter(r=>ids.has(r.source)&&ids.has(r.target)&&visibleSources.has('inventory')),collectors:base.collectors.map((c,i)=>i>=replayIndex&&c.status==='complete'?{...c,status:'pending',count:0,detail:'Sample source queued for replay.'}:c)};
}
function render(){
  if(!report)return;
  const data=activeReport(),m=metrics(data),issues=insights(data),info=viewInfo[view];
  $('company-sidebar').textContent=data.company;
  document.querySelector('.workspace-avatar').textContent=initials(data.company);
  $('inventory-count').textContent=m.systems;$('gap-count').textContent=issues.length;
  $('breadcrumb').textContent=info[0];$('view-title').textContent=info[1];$('view-subtitle').textContent=info[2];
  document.querySelectorAll('.nav-item').forEach(button=>{button.classList.toggle('active',button.dataset.view===view);if(button.dataset.view===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
  const isDemo=data.mode==='demo';
  $('mode-badge').textContent=isDemo?'Sample company':'Agent report';$('mode-badge').className='mode-badge'+(isDemo?'':' live');
  $('demo-notice').className='demo-notice'+(isDemo?'':' live-notice');
  $('demo-notice').innerHTML=isDemo?'<span class="sample-icon">◈</span><span><b>Investor sandbox.</b> Fictional company and sample evidence. Import an agent report to explore real findings.</span><button id="sample-reset">Reset sample</button>':'<span class="sample-icon">◇</span><span><b>Agent report.</b> Viewing supplied findings in this browser. Nothing is uploaded. Source coverage remains limited to this scan.</span><button id="sample-reset">Load sample</button>';
  $('replay').innerHTML=timer?'Stop replay <span>□</span>':isDemo?'Replay discovery <span>↻</span>':'Open sample demo <span>↻</span>';
  $('stats').innerHTML=[['Systems discovered',m.systems,`${m.evidence} evidence records`,'In this scan'],['Business functions',m.functions,'Mapped from system categories','Company context'],['Integration links',m.links,'Only links with supplied evidence','Observed or reported'],['Sources completed',`${m.complete}<span>/ ${m.configured} enabled</span>`,`${data.collectors.filter(c=>c.status==='not_configured').length} not configured`,'Discovery scope']].map(([label,value,note,caption])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`).join('');
  $('view-content').innerHTML=view==='map'?renderMap(data):view==='inventory'?renderInventory(data):view==='sources'?renderSources(data):renderInsights(data);
  $('scan-time').textContent=(isDemo?'Sample snapshot':'Scan snapshot')+' · '+new Date(data.generated_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
  bindView();
}

function renderMap(data){
  const list=[...data.systems].sort((a,b)=>categories.indexOf(a.category)-categories.indexOf(b.category)).slice(0,12);
  const n=list.length, cx=450,cy=292;
  const pos=new Map(list.map((a,i)=>{const angle=-Math.PI/2+i*2*Math.PI/Math.max(n,1);return [a.id,{x:cx+340*Math.cos(angle),y:cy+213*Math.sin(angle)}];}));
  const membership=list.map(a=>{const p=pos.get(a.id);return `<line class="membership" x1="${cx}" y1="${cy}" x2="${p.x}" y2="${p.y}"/>`;}).join('');
  const edges=data.relationships.filter(r=>pos.has(r.source)&&pos.has(r.target)).map(r=>{const a=pos.get(r.source),b=pos.get(r.target);return `<path class="integration ${escape(r.status)}" d="M${a.x},${a.y} Q${cx},${cy-35} ${b.x},${b.y}"><title>${escape(r.label)} · ${escape(r.status)}</title></path>`;}).join('');
  const nodes=list.map(a=>{const p=pos.get(a.id),name=a.name.length>20?a.name.slice(0,18)+'…':a.name;return `<g class="graph-node" tabindex="0" role="button" aria-label="Inspect ${escape(a.name)}" data-system="${escape(a.id)}" transform="translate(${p.x-83},${p.y-28})"><rect class="node-box" width="166" height="57" rx="8"/><rect x="10" y="13" width="29" height="29" rx="7" fill="${colors[a.category]}" fill-opacity=".1"/><text class="node-initial" text-anchor="middle" x="24.5" y="32" fill="${colors[a.category]}">${escape(initials(a.name))}</text><text class="node-name" x="48" y="24">${escape(name.length>16?name.slice(0,15)+'…':name)}</text><text class="node-sub" x="48" y="42">${escape(a.category)} · ${a.evidence.length} ${a.evidence.length===1?'clue':'clues'}</text><title>${escape(a.name)} — ${escape(a.category)} — ${escape(a.status)}</title></g>`;}).join('');
  const issues=insights(data),featured=issues[0];
  const label=timer?(replayIndex===0?'Waiting to replay source 1':`Replaying ${Math.min(replayIndex,data.collectors.length)} / ${data.collectors.length} sample sources`):'Select a system to inspect';
  const canvas=n?`<svg viewBox="0 0 900 585" role="group" aria-label="Company system map. Dotted lines indicate inventory membership. Integration lines have separate evidence.">${membership}${edges}<circle class="org-orbit" cx="450" cy="292" r="105"/><circle class="org-ring" cx="450" cy="292" r="88"/><text x="450" y="271" class="org-label" text-anchor="middle">COMPANY MODEL</text><text x="450" y="301" class="org-name" text-anchor="middle">${escape(data.company.length>18?data.company.slice(0,17)+'…':data.company)}</text><text x="450" y="324" text-anchor="middle" fill="#8cae9f" font-size="11">${data.systems.length} systems in view</text>${nodes}</svg>`:`<div class="empty"><h3>${timer?'Sensing the sample company…':'No systems in this report yet'}</h3><p>${timer?'The replay will reveal the sample evidence, source by source.':'Inspect Discovery sources for errors, or run an enabled collector and import its report.'}</p></div>`;
  return `<div class="map-layout"><div class="panel"><div class="panel-head"><div><h2>The company, connected.</h2><p>Systems → evidence → a shared operating model</p></div><span class="small-label ${timer?'replay-label':''}">${label}</span></div>${timer?`<div class="replay-progress" role="progressbar" aria-label="Sample discovery replay" aria-valuemin="0" aria-valuemax="${data.collectors.length}" aria-valuenow="${replayIndex}"><span style="width:${100*replayIndex/data.collectors.length}%"></span></div>`:''}<div class="map-canvas">${canvas}</div><div class="map-legend"><span><i class="legend-line member"></i>Inventory membership</span>${['observed','reported','inferred'].filter(status=>data.relationships.some(r=>r.status===status)).map(status=>`<span><i class="legend-line ${status}"></i>${status==='observed'?'Observed':status==='reported'?'Reported':'Inferred'} integration</span>`).join('')}<span class="legend-note">Membership does not imply data flow</span></div>${data.systems.length>12?`<div class="map-overflow">Showing 12 of ${data.systems.length} systems. <button class="text-button" data-go="inventory">View full inventory →</button></div>`:''}</div><div class="side-panel"><div class="insight-feature"><div class="feature-top"><span>WHAT THE EVIDENCE SAYS</span><span>◇</span></div><div class="feature-symbol">⌁</div><h3>${escape(featured?.title||'A starting point for understanding.')}</h3><p>${escape(featured?.body||'Inspect the collected systems and confirm their business purpose with the people who use them.')}</p><div class="mini-tags">${(featured?.ids||[]).slice(0,3).map(id=>`<span class="mini-tag">${escape(data.systems.find(s=>s.id===id)?.name)}</span>`).join('')}</div><div class="feature-footer"><span>Rule-based finding</span><button class="text-button" data-go="insights">Review gaps ↗</button></div></div><div class="panel scope-card"><h3>Visibility has a boundary.</h3><p>This map reflects the sources in this scan. Unconnected SaaS accounts, other endpoints, and isolated networks may be missing.</p><button class="text-button" data-go="sources">Inspect discovery scope →</button></div></div></div><div class="panel below-map"><div class="panel-head"><h2>Connections with evidence</h2><span class="small-label">${data.relationships.length} reported or observed</span></div>${data.relationships.length?data.relationships.map(r=>`<div class="relationship-row"><button data-system="${escape(r.source)}">${escape(data.systems.find(s=>s.id===r.source)?.name)}</button><span class="muted">→</span><button data-system="${escape(r.target)}">${escape(data.systems.find(s=>s.id===r.target)?.name)}</button><span class="relation-label">${escape(r.label)}</span>${badge(r.status)}</div>`).join(''):'<div class="scope-card"><p>No integration evidence supplied. Systems appearing together do not establish a connection.</p></div>'}</div>`;
}
function rows(data){return filterSystems(data,query,category,state).map(s=>`<tr><td><div class="system-cell"><span class="system-icon" style="--cat:${colors[s.category]}">${escape(initials(s.name))}</span><div><button class="system-name" data-system="${escape(s.id)}">${escape(s.name)}</button><small>${s.evidence.length} evidence ${s.evidence.length===1?'record':'records'}</small></div></div></td><td>${escape(s.category)}</td><td>${s.owner?escape(s.owner):'<span class="owner-missing">Unassigned</span>'}</td><td>${badge(s.status)}</td><td><button class="text-button" data-system="${escape(s.id)}">Inspect ↗</button></td></tr>`).join('');}
function renderInventory(data){const found=filterSystems(data,query,category,state);return `<div class="panel"><div class="toolbar"><input id="system-search" type="search" placeholder="Search systems, owners, sources…" aria-label="Search systems" value="${escape(query)}"><select id="category-filter" aria-label="Filter by business function"><option value="all">All functions</option>${categories.map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select><select id="status-filter" aria-label="Filter by evidence status"><option value="all">All evidence</option>${['observed','reported','inferred'].map(c=>`<option value="${c}" ${state===c?'selected':''}>${c==='observed'?'Observed':c==='reported'?'Owner reported':'Needs verification'}</option>`).join('')}</select><button class="button small" id="export-csv">Export CSV ↓</button></div><div class="table-scroll"><table><thead><tr><th>SYSTEM</th><th>FUNCTION</th><th>OWNER / TEAM</th><th>EVIDENCE STATUS</th><th>DETAILS</th></tr></thead><tbody id="system-rows">${rows(data)}</tbody></table><div id="no-results" class="empty" ${found.length?'hidden':''}><h3>No matching systems</h3><p>Try another name or reset the function and evidence filters.</p></div></div><div class="table-foot"><span id="result-count">${found.length} of ${data.systems.length} systems</span><span>Observed means a source record exists; active use is unverified.</span></div></div>`;}
function renderSources(data){return `<div class="scope-banner"><span>◎</span><div><h3>Total company coverage is unknown.</h3><p>Completion describes a configured source, not the percentage of your company discovered. Add more endpoints and authorized sources to expand visibility.</p></div></div><div class="sources-grid">${data.collectors.map(c=>`<div class="panel source-card"><div class="source-top"><span>${escape(sourceNames[c.id]||c.id)}</span>${badge(c.status)}</div><h3>${escape(c.name)}</h3><div class="source-detail">${escape(c.detail)}</div><div class="source-footer"><span>${c.count} findings before deduplication</span>${data.mode==='demo'?'<span>Sample evidence</span>':'<span>Agent outcome</span>'}</div></div>`).join('')}</div><div class="panel below-map scope-card"><h3>Collection boundaries</h3>${(data.limitations||[]).map(l=>`<p>• ${escape(l)}</p>`).join('')}<p>Microsoft 365 requires a company administrator to approve application-read access. Endpoint discovery examines only the machine running the agent. DNS discovery sends approved domain names to Cloudflare's resolver.</p></div>`;}
function renderInsights(data){const items=insights(data);return `<div class="scope-banner"><span>◇</span><div><h3>Questions supported by evidence.</h3><p>These findings use transparent inventory rules. They do not represent an AI diagnosis, financial estimate, or operational action.</p></div></div><div class="insights-grid">${items.map((i,index)=>`<div class="panel insight-card"><div class="source-top"><span class="insight-kind">${escape(i.kind)}</span><span>0${index+1}</span></div><h3>${escape(i.title)}</h3><p>${escape(i.body)}</p><div class="insight-assets">${i.ids.slice(0,7).map(id=>`<button class="asset-chip" data-system="${escape(id)}">${escape(data.systems.find(s=>s.id===id)?.name)}</button>`).join('')}${i.ids.length>7?`<span class="asset-chip">+${i.ids.length-7} more</span>`:''}</div><button class="text-button" data-go="${i.kind==='Visibility'?'sources':'inventory'}">${i.kind==='Visibility'?'Inspect sources':'Review inventory'} →</button></div>`).join('')||'<div class="panel empty"><h3>No rules triggered</h3><p>This is not a clean bill of health. Review discovery scope and validate active use with system owners.</p></div>'}</div>`;}
function openSystem(id){
  const data=activeReport(),s=data.systems.find(s=>s.id===id);if(!s)return;
  const related=data.relationships.filter(r=>r.source===id||r.target===id);
  $('detail-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">SYSTEM EVIDENCE</span><button class="icon-button close-dialog" aria-label="Close system details">×</button></div><div class="detail-heading"><span class="system-icon" style="--cat:${colors[s.category]}">${escape(initials(s.name))}</span><div><h2 id="detail-title">${escape(s.name)}</h2>${badge(s.status)}</div></div><div class="detail-summary"><div><small>BUSINESS FUNCTION</small><b>${escape(s.category)}</b></div><div><small>OWNER / TEAM</small><b>${escape(s.owner||'Unassigned')}</b></div><div><small>DETECTION SCORE</small><b>${s.confidence} / 100</b></div></div><h3>Why this system is on the map</h3>${s.evidence.map(e=>`<div class="evidence-card"><div class="evidence-top"><b>${escape(sourceNames[e.source]||e.source)}</b>${badge(e.status)}</div><p>${escape(e.summary)}</p><div class="evidence-meta">${escape(e.locator||'Source metadata')}<br>${escape(new Date(e.observed_at).toLocaleString())} · Evidence ${escape(e.id)}</div></div>`).join('')}${related.length?`<h3 style="margin-top:24px">Connection evidence</h3>${related.map(r=>`<div class="evidence-card"><div class="evidence-top"><b>${escape(r.label)}</b>${badge(r.status)}</div><p>${escape(r.evidence)}</p></div>`).join('')}`:''}<div class="detail-note">Detection scores are rule-based signal strengths, not statistical probabilities. A source record does not verify active use, ownership, operational health, or a live integration.</div>`;
  $('details').showModal();bindClose();
}
function changeView(next){view=next;render();}
function bindSystemButtons(root=document){root.querySelectorAll('[data-system]').forEach(el=>{el.onclick=()=>openSystem(el.dataset.system);if(el.tagName.toLowerCase()==='g')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openSystem(el.dataset.system);}};});}
function bindClose(){document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());}
function bindView(){
  bindSystemButtons();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>changeView(b.dataset.go));
  $('sample-reset').onclick=resetSample;
  if(view==='inventory'){
    function updateTable(){const data=activeReport();$('system-rows').innerHTML=rows(data);const n=filterSystems(data,query,category,state).length;$('no-results').hidden=n>0;$('result-count').textContent=`${n} of ${data.systems.length} systems`;bindSystemButtons($('system-rows'));}
    $('system-search').oninput=e=>{query=e.target.value;updateTable();};$('category-filter').onchange=e=>{category=e.target.value;updateTable();};$('status-filter').onchange=e=>{state=e.target.value;updateTable();};
    $('export-csv').onclick=()=>{saveFile('glinx-inventory.csv',inventoryCsv(report),'text/csv;charset=utf-8');notify('Full inventory exported as CSV.');};
  }
}
function resetSample(){if(!sample){notify('The sample report is unavailable. Reload the page to try again.',true);return;}stopReplay();report=structuredClone(sample);query='';category=state='all';render();notify('Fictional Alder Forge sample restored.');}
function replay(){
  if(timer){stopReplay();report=structuredClone(sample);render();notify('Replay stopped. Full sample restored.');return;}
  if(!sample){notify('The sample report is unavailable.',true);return;}
  if(report.mode!=='demo'){resetSample();return;}
  // Only the packaged fictional fixture is ever replayed. Imported data stays a snapshot.
  report=structuredClone(sample);replayBase=sample;view='map';replayIndex=0;
  timer=setInterval(()=>{replayIndex++;if(replayIndex>=sample.collectors.length){stopReplay();report=structuredClone(sample);render();notify('Sample replay complete. Select any system to inspect its evidence.');}else render();},1450);render();
}
async function importFile(file){
  if(!file)return;
  try{if(file.size>5_000_000)throw new Error('Reports must be smaller than 5 MB.');const loaded=validateReport(JSON.parse(await file.text()));stopReplay();report=loaded;query='';category=state='all';render();notify(`Loaded ${loaded.systems.length} systems. This report stays in this tab.`);}catch(e){notify(e.message||'Unable to read this report.',true);}finally{$('report-file').value='';}
}
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>changeView(b.dataset.view));
$('load-report').onclick=()=>$('report-file').click();$('report-file').onchange=e=>importFile(e.target.files[0]);
$('install-agent').onclick=()=>$('install-dialog').showModal();bindClose();
$('export-report').onclick=()=>{if(!report)return;saveFile('glinx-report.json',JSON.stringify(report,null,2),'application/json');notify('Full report exported.');};
$('replay').onclick=replay;
document.querySelectorAll('.copy-code').forEach(b=>b.onclick=async()=>{const code=b.dataset.copy==='install'?'git clone https://github.com/dennybrig/Glinx.ai.git\ncd Glinx.ai\npython -m pip install .':'glinx scan --host --company "My company" --serve';try{await navigator.clipboard.writeText(code);notify('Command copied.');}catch{notify('Select and copy the command shown above.',true);}});
document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
async function loadJson(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(`Report request failed (${r.status}).`);return validateReport(await r.json());}
async function boot(){
  $('view-content').innerHTML='<div class="loading-note">Loading company evidence…</div>';
  const results=await Promise.allSettled([loadJson('./initial.json'),loadJson('./demo.json')]);
  if(results[1].status==='fulfilled')sample=results[1].value;
  if(results[0].status==='fulfilled'){report=results[0].value;render();}
  else{$('view-content').innerHTML='<div class="error-state"><h2>The report could not be loaded.</h2><p>Reload the page or import a valid Glinx report. A sample will not silently replace a failed company report.</p></div>';notify('Initial report failed to load. You can import a scan or use Reset sample.',true);$('sample-reset').onclick=resetSample;}
}
boot();
